"""Same-origin, dependency-free operator and workspace console."""


CONSOLE_HTML = r'''<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>Render Bridge Pool</title><style>
:root{font:15px/1.45 system-ui,sans-serif;color:#16212b;background:#f3f6f8}*{box-sizing:border-box}body{margin:0}
header{background:#122736;color:#fff;padding:22px max(20px,calc((100vw - 1100px)/2))}main{max-width:1100px;margin:24px auto;padding:0 18px}
h1{font-size:22px;margin:0}h2{font-size:17px;margin:0 0 14px}section{background:white;border:1px solid #dbe3e8;border-radius:10px;padding:18px;margin:14px 0}
.row{display:flex;gap:10px;align-items:end;flex-wrap:wrap}.field{display:flex;flex-direction:column;gap:4px;min-width:170px;flex:1}label{font-size:13px;color:#435563}
input,select,button{font:inherit;padding:9px 10px;border:1px solid #aebdc7;border-radius:6px;background:white;color:inherit}button{cursor:pointer;background:#185b7b;color:white;border-color:#185b7b}button.secondary{background:white;color:#185b7b}button.danger{background:#a63838;border-color:#a63838}
button:disabled{opacity:.5;cursor:default}.muted{color:#657580;font-size:13px}.status{min-height:1.5em;margin:9px 0;color:#245c43}.error{color:#a63838}table{width:100%;border-collapse:collapse;margin-top:12px}th,td{text-align:left;padding:8px;border-bottom:1px solid #e6ecef;vertical-align:top;font-size:13px}th{color:#526572}
pre,code{white-space:pre-wrap;word-break:break-all;background:#f2f6f8;border-radius:6px;padding:10px;display:block}details{margin-top:10px}nav{display:flex;gap:8px;flex-wrap:wrap;margin:12px 0}nav button[aria-pressed="true"]{background:#122736}
.hidden{display:none!important}.notice{background:#fff8df;border-left:4px solid #c88d11;padding:12px;margin:10px 0}footer{color:#657580;font-size:12px;padding:10px 0 30px}
@media(max-width:650px){section{padding:14px}table{display:block;overflow:auto}}
</style></head><body><header><h1>Render Bridge · Shared Pool</h1><div class="muted" style="color:#c7d7df">One Bridge service · opt-in workspaces · independent node agents</div></header>
<main><section><h2>Connect</h2><div class="row"><div class="field"><label for="role">Access type</label><select id="role"><option value="operator">Operator</option><option value="workspace">Workspace</option></select></div>
<div class="field" style="flex:4"><label for="token">Bearer token</label><input id="token" type="password" autocomplete="off" spellcheck="false"></div><button id="connect">Connect</button></div><p class="muted">The token stays in this page's memory and clears when you close or reload it. Use HTTPS outside loopback.</p><div id="message" class="status" role="status" aria-live="polite"></div></section>
<section id="operator" class="hidden"><h2>Fleet overview</h2><div id="summary" class="muted">Connect to load status.</div><div class="row" style="margin-top:12px"><div class="field"><label for="poolName">New pool name</label><input id="poolName" maxlength="80"></div><button id="createPool">Create pool</button></div><div id="pools"></div>
<div class="row" style="margin-top:14px"><div class="field"><label for="poolSelect">Pool</label><select id="poolSelect"></select></div><div class="field"><label for="inviteKind">Invite type</label><select id="inviteKind"><option value="node">Node operator</option><option value="workspace">Workspace</option></select></div><div class="field"><label for="profiles">Node profiles (comma separated)</label><input id="profiles" value="fake-image"></div><button id="createInvite">Create one-use invite</button></div><div id="inviteResult"></div>
<h2 style="margin-top:22px">Workspace credential</h2><div class="row"><div class="field"><label for="sourceId">Source ID</label><input id="sourceId" maxlength="128"></div><div class="field"><label for="workspaceId">Workspace ID</label><input id="workspaceId" maxlength="128"></div><button id="createCredential">Create source token</button></div><div id="credentialResult"></div>
<h2 style="margin-top:22px">Nodes</h2><div class="row"><button class="secondary" id="refreshNodes">Refresh</button><span id="fleetRefreshState" class="muted" role="status" aria-live="polite">Auto-refresh starts after connect.</span></div><div id="nodes"></div>
<h2 style="margin-top:22px">Task history</h2><div class="row"><div class="field"><label for="statusFilter">Status filter</label><select id="statusFilter"><option value="">All</option><option>queued</option><option>running</option><option>execution_unknown</option><option>awaiting_user</option><option>uploading</option><option>artifacts_ready</option><option>failed</option><option>canceled</option><option>expired</option></select></div><button id="refreshHistory">Load history</button><button class="secondary" id="moreHistory">More</button></div><div id="history"></div></section>
<section id="workspace" class="hidden"><h2>Workspace</h2><p class="notice">Before joining: prompts and reference images for tasks you submit to this pool can be downloaded to a pool member's machine. Generated files return to the Bridge and remain scoped to your workspace.</p><div class="row"><div class="field"><label for="inviteCode">One-use workspace invitation</label><input id="inviteCode" autocomplete="off" spellcheck="false"></div><button id="joinPool">Review and join</button></div><div id="workspaceResult"></div><h2 style="margin-top:22px">Pool membership</h2><div id="workspaceMemberships"></div><h2 style="margin-top:22px">My task history</h2><button id="workspaceHistory">Refresh</button><div id="workspaceTasks"></div></section>
<footer>Browser UI reports Bridge ledger state. It cannot start a process on a remote machine; use the displayed local Agent command and manage it on that machine.</footer></main>
<script>
(()=>{const $=id=>document.getElementById(id),msg=$('message');let token='',role='operator',cursor=null,operatorConnected=false,refreshTimer=null,operatorRefresh=null,sessionAbort=null,sessionGeneration=0;
const FLEET_REFRESH_MS=5000;
function setMsg(text,error=false){msg.textContent=text;msg.className='status'+(error?' error':'')}
function node(tag,text,cls){const e=document.createElement(tag);if(text!==undefined)e.textContent=String(text);if(cls)e.className=cls;return e}
function stopOperatorAutoRefresh(){if(refreshTimer!==null){clearTimeout(refreshTimer);refreshTimer=null}}
function scheduleOperatorAutoRefresh(){stopOperatorAutoRefresh();if(!operatorConnected||role!=='operator'||!token||document.hidden)return;refreshTimer=setTimeout(()=>{refreshTimer=null;refreshOperator().catch(()=>{})},FLEET_REFRESH_MS)}
function beginSession(){stopOperatorAutoRefresh();if(sessionAbort)sessionAbort.abort();sessionGeneration+=1;sessionAbort=new AbortController();operatorRefresh=null;return sessionGeneration}
function psQuote(value){return "'"+String(value).replace(/'/g,"''")+"'"}
async function api(path,method='GET',body){const r=await fetch(path,{method,headers:{'Authorization':'Bearer '+token,...(body?{'Content-Type':'application/json'}:{})},body:body?JSON.stringify(body):undefined,cache:'no-store',signal:sessionAbort?.signal});let data={};try{data=await r.json()}catch{}if(!r.ok)throw new Error(data?.error?.code||'request_failed');return data}
function table(target,headers,rows){target.replaceChildren();if(!rows.length){target.append(node('p','No records yet.','muted'));return}const t=node('table'),head=node('tr');headers.forEach(h=>head.append(node('th',h)));const thead=node('thead');thead.append(head);t.append(thead);const body=node('tbody');rows.forEach(vals=>{const tr=node('tr');vals.forEach(v=>{const td=node('td');if(v instanceof Node)td.append(v);else td.textContent=v??'—';tr.append(td)});body.append(tr)});t.append(body);target.append(t)}
async function connect(){const generation=beginSession();operatorConnected=false;token=$('token').value;role=$('role').value;cursor=null;if(!token){setMsg('Enter a token.',true);return}try{if(role==='operator'){$('operator').classList.remove('hidden');$('workspace').classList.add('hidden');operatorConnected=true;await refreshOperator()}else{$('workspace').classList.remove('hidden');$('operator').classList.add('hidden');await refreshWorkspace()}if(generation===sessionGeneration)setMsg('Connected.')}catch(e){if(generation!==sessionGeneration)return;operatorConnected=false;stopOperatorAutoRefresh();$('operator').classList.add('hidden');$('workspace').classList.add('hidden');setMsg('Could not connect: '+e.message,true)}}
async function refreshOperator(){if(operatorRefresh)return operatorRefresh;const generation=sessionGeneration;const pending=(async()=>{try{const [summary,pools,nodes]=await Promise.all([api('/bridge/control/v2/summary'),api('/bridge/control/v2/pools'),api('/bridge/control/v2/nodes')]);if(generation!==sessionGeneration)return;$('summary').textContent=`${summary.pools_active} pools · ${summary.workspaces_joined} workspaces · ${summary.nodes_online}/${summary.nodes_active} nodes online · slots ${summary.slots_used}/${summary.slots_total} in use · ${summary.queued_tasks} queued · ${summary.active_assignments} active assignments`;
const sel=$('poolSelect'),old=sel.value;sel.replaceChildren();pools.forEach(p=>{const o=node('option',p.name);o.value=p.pool_id;sel.append(o)});if(pools.some(p=>p.pool_id===old))sel.value=old;table($('pools'),['Pool','State','Policy'],pools.map(p=>[p.name,p.state,p.policy_version]));renderNodes(nodes.nodes);$('fleetRefreshState').textContent='Updated '+new Date().toLocaleTimeString()+' · refreshes every 5 seconds'}catch(e){if(generation===sessionGeneration)$('fleetRefreshState').textContent='Refresh failed; retrying in 5 seconds. '+e.message;throw e}finally{if(generation===sessionGeneration&&operatorConnected)scheduleOperatorAutoRefresh()}})();operatorRefresh=pending;try{await pending}finally{if(operatorRefresh===pending)operatorRefresh=null}}
async function refreshWorkspace(){const memberships=await api('/bridge/source/v2/pools');const holder=node('div');for(const p of memberships.pools||[]){const card=node('section');card.append(node('strong',p.pool_name+' · '+p.membership+' · '+p.pool_state));card.append(node('p','Joined '+p.joined_at));if(p.membership==='active'){const leave=node('button','Leave this pool','secondary');leave.onclick=async()=>{try{await api('/bridge/source/v2/pools/'+encodeURIComponent(p.pool_id)+'/leave','POST',{});setMsg('Left the pool. Future assignments are blocked.');await refreshWorkspace()}catch(e){setMsg(e.message,true)}};card.append(leave)}holder.append(card)}if(!holder.childNodes.length)holder.append(node('p','No pool memberships.','muted'));$('workspaceMemberships').replaceChildren(holder);const r=await api('/bridge/source/v2/tasks?limit=50');table($('workspaceTasks'),['Task','Status','Profile','Node','Created','Reason'],r.items.map(x=>[x.task_id,x.status,x.profile_id,x.node_id||'—',x.created_at,x.reason_code||'—']))}
function renderNodes(nodes){table($('nodes'),['Pool / node','State','Last heartbeat','Profiles','Current assignment','Controls'],nodes.map(n=>{const meta=node('div');meta.textContent=n.pool_name+' · '+n.node_id+' / '+n.executor_instance;const a=n.current_assignment?`${n.current_assignment.task_id} · ${n.current_assignment.workspace_id} · ${n.current_assignment.task_state}`:'Free';const actions=node('div');[['drain','Drain','secondary'],['reactivate','Resume','secondary'],['revoke','Revoke','danger']].forEach(([verb,label,cls])=>{const b=node('button',label,cls);b.type='button';b.onclick=async()=>{if(!confirm(`${label} ${n.node_id}?`))return;try{await api(`/bridge/control/v2/pools/${encodeURIComponent(n.pool_id)}/nodes/${encodeURIComponent(n.node_id)}/${encodeURIComponent(n.executor_instance)}/${verb}`,'POST',{});await refreshOperator();setMsg('Node state updated.')}catch(e){setMsg(e.message,true)}};actions.append(b)});return [meta,n.state+' · '+n.liveness,n.last_seen_at||'—',n.profiles.join(', '),a,actions]}))}
async function loadHistory(append=false){try{if(!append)cursor=null;const q=new URLSearchParams({limit:'30'});const s=$('statusFilter').value;if(s)q.set('status',s);if(cursor)q.set('cursor',cursor);const r=await api('/bridge/control/v2/tasks?'+q);cursor=r.next_cursor;const target=$('history');if(!append)target.replaceChildren();const rows=(r.items||[]).map(x=>{const b=node('button',x.task_id,'secondary');b.onclick=async()=>{try{const d=await api('/bridge/control/v2/tasks/'+encodeURIComponent(x.task_id));const box=node('details');box.open=true;box.append(node('summary','Task details and timeline'));box.append(node('pre',JSON.stringify(d,null,2)));target.prepend(box)}catch(e){setMsg(e.message,true)}};return [b,x.workspace_id,x.status,x.profile_id,x.node_id||'—',x.created_at,x.reason_code||'—']});const holder=node('div');table(holder,['Task','Workspace','Status','Profile','Node','Created','Reason'],rows);target.append(...holder.childNodes);$('moreHistory').disabled=!cursor}catch(e){setMsg('History error: '+e.message,true)}}
$('connect').onclick=connect;$('createPool').onclick=async()=>{try{const p=await api('/bridge/control/v2/pools','POST',{name:$('poolName').value});setMsg('Pool created: '+p.pool_id);await refreshOperator()}catch(e){setMsg(e.message,true)}};
$('createInvite').onclick=async()=>{try{const kind=$('inviteKind').value;const profiles=$('profiles').value.split(',').map(x=>x.trim()).filter(Boolean);const r=await api(`/bridge/control/v2/pools/${encodeURIComponent($('poolSelect').value)}/invites`,'POST',{kind,ttl_seconds:3600,...(kind==='node'?{profiles}:{})});const box=node('section');box.append(node('p','One-use '+kind+' invite; share it through a trusted channel.'));box.append(node('code',r.invite_code));if(kind==='node'){box.append(node('p','First setup on Windows: open PowerShell in the Bridge release folder and run the command below. It prepares the isolated environment, asks for sharing consent and the invite code without echoing it, then starts the Agent. Later starts can use the batch launcher.'));box.append(node('code','powershell.exe -NoProfile -ExecutionPolicy Bypass -File .\\scripts\\start_shared_pool_node.ps1 -Url '+psQuote(location.origin)+' -Profiles '+psQuote(profiles.join(','))));box.append(node('p','Keep the PowerShell window open while this node is online. On other systems, install this Bridge release and use the Python enroll/run commands documented with the release.'));} $('inviteResult').replaceChildren(box);setMsg('Invite created and shown once.')}catch(e){setMsg(e.message,true)}};
$('createCredential').onclick=async()=>{try{const r=await api('/bridge/control/v2/source-credentials','POST',{source_id:$('sourceId').value,workspace_id:$('workspaceId').value});const box=node('section');box.append(node('p','Copy this source token now. It will not be shown again.'));box.append(node('code',r.source_token));$('credentialResult').replaceChildren(box);setMsg('Source token created.')}catch(e){setMsg(e.message,true)}};
$('refreshNodes').onclick=async()=>{try{await refreshOperator();setMsg('Fleet refreshed.')}catch(e){setMsg(e.message,true)}};$('refreshHistory').onclick=()=>loadHistory(false);$('moreHistory').onclick=()=>loadHistory(true);
$('joinPool').onclick=async()=>{try{const code=$('inviteCode').value;const preview=await api('/bridge/source/v2/pool-invites/inspect','POST',{invite_code:code});const box=node('div');box.append(node('p',preview.sharing_disclosure));const b=node('button','I understand; join '+preview.pool_name);b.onclick=async()=>{try{const done=await api('/bridge/source/v2/pool-invites/accept','POST',{invite_code:code,accept_shared_data:true});setMsg('Workspace joined: '+done.pool_name+'.');await refreshWorkspace()}catch(e){setMsg(e.message,true)}};box.append(b);$('workspaceResult').replaceChildren(box)}catch(e){setMsg(e.message,true)}};
$('workspaceHistory').onclick=async()=>{try{await refreshWorkspace()}catch(e){setMsg(e.message,true)}};
document.addEventListener('visibilitychange',()=>{if(document.hidden)stopOperatorAutoRefresh();else if(operatorConnected)refreshOperator().catch(()=>{})});window.addEventListener('beforeunload',()=>{stopOperatorAutoRefresh();if(sessionAbort)sessionAbort.abort()});
})();
</script></body></html>'''
